// Merge results from parallel calls
const prepareData = $('Prepare Data').first().json;
const text = prepareData.text;
const options = prepareData.options;
const startTime = prepareData.startTime;

// Get Google Sentiment result
let sentimentResult = null;
try {
  const googleSentiment = $('Google Sentiment').first().json;
  if (googleSentiment && googleSentiment.documentSentiment) {
    const ds = googleSentiment.documentSentiment;
    sentimentResult = {
      sentiment: ds.score > 0.2 ? 'positive' : ds.score < -0.2 ? 'negative' : 'neutral',
      score: ds.score,
      magnitude: ds.magnitude,
      confidence: Math.min(1, Math.abs(ds.score) + ds.magnitude / 2)
    };
  }
} catch (e) {
  sentimentResult = { error: 'Google Sentiment failed', fallback: true };
}

// Get Google Entities result
let entitiesResult = [];
try {
  const googleEntities = $('Google Entities').first().json;
  if (googleEntities && googleEntities.entities) {
    entitiesResult = googleEntities.entities.map(e => ({
      type: e.type,
      value: e.name,
      salience: e.salience,
      metadata: e.metadata || {}
    }));
  }
} catch (e) {
  entitiesResult = [];
}

// Get OpenAI result
let intentResult = null;
let priorityResult = null;
let languageResult = null;

try {
  const openaiResponse = $('OpenAI Intent+Priority').first().json;
  if (openaiResponse && openaiResponse.choices && openaiResponse.choices[0]) {
    const content = openaiResponse.choices[0].message.content;
    const parsed = JSON.parse(content);

    intentResult = parsed.intent || null;
    priorityResult = parsed.priority || null;
    languageResult = parsed.language || null;
  }
} catch (e) {
  // Fallback values
  intentResult = { intent: 'unknown', confidence: 0, error: 'OpenAI parsing failed' };
  priorityResult = { priority: 'medium', score: 0.5 };
  languageResult = { language: 'unknown', confidence: 0 };
}

// Build final response
const response = {
  success: true,
  text: text,
  analysis: {}
};

if (options.sentiment !== false) {
  response.analysis.sentiment = sentimentResult;
}

if (options.intent !== false) {
  response.analysis.intent = intentResult;
}

if (options.entities !== false) {
  response.analysis.entities = entitiesResult;
}

if (options.priority !== false) {
  response.analysis.priority = priorityResult;
}

if (options.language !== false) {
  response.analysis.language = languageResult;
}

response.meta = {
  providers: {
    sentiment: 'google-cloud-nlp',
    entities: 'google-cloud-nlp',
    intent: 'openai-gpt4o-mini',
    priority: 'openai-gpt4o-mini',
    language: 'openai-gpt4o-mini'
  },
  processing_time_ms: Date.now() - startTime
};

return { json: response };
